 if(values.address){ctx.font='24px Arial, sans-serif';const lines=wrap(ctx,values.address,lower.width);if(lines.length>2)throw Error('Adres en fazla iki satıra sığmalı. Lütfen adresi kısaltın.');plans.push({type:'address',x:lower.x,y:lower.y+(lower.height-lines.length*32)/2,width:lower.width,height:lines.length*32,font:24,lineHeight:32,lines:lines.map(text=>({text,key:'address'}))});}
